function renderEssays(root){
 ESSAYS.forEach(([n,title])=>{
  const row=document.createElement('a');row.className='essay-entry essay-external';
  row.href=ESSAY_LINKS[n];row.target='_blank';row.rel='noopener noreferrer';
  row.setAttribute('aria-label',title+' — 새 탭에서 블로그 열기');
  const num=document.createElement('span');num.textContent=n;
  const label=document.createElement('strong');label.textContent=title;
  const arrow=document.createElement('span');arrow.className='essay-arrow';arrow.textContent='↗';
  row.append(num,label,arrow);root.append(row);
 });
}
